//! `experimental_image_generate`: make or edit an image with an image model,
//! in the background (after OpenCode's `ImageGenerateTool`).
//!
//! The call checks everything that needs the user or can fail fast (the
//! model, the permissions, the input images), then starts a background job
//! and returns at once; the session is told when the image is saved. The
//! file takes the extension of the image's real format. The generated bytes
//! go through the session's blob store on the way to the file, so the
//! session keeps one copy of each image it made.

use super::{shell::Jobs, Ctx};
use crate::config::Config;
use crate::generate::{self, MediaModel};
use crate::permission::{Gate, Request};
use codesmith_ai::Media;
use serde_json::{json, Value};
use std::path::{Path, PathBuf};
use std::time::Duration;

pub const NAME: &str = "experimental_image_generate";

/// The largest input image.
pub const MAX_INPUT_BYTES: u64 = 20 * 1024 * 1024;
const DOWNLOAD_TIMEOUT: Duration = Duration::from_secs(30);
const INPUT_TYPES: [&str; 4] = ["image/png", "image/jpeg", "image/webp", "image/gif"];

pub const DESCRIPTION: &str = "Generates a new image, or edits existing ones.
Only call this when the user asks you to create or edit an image. If you think an image would help but the user didn't ask for one, ask them first instead of generating it.
Images you pass are used as the source to edit, or as references for style and subject.
Each call makes one image. For several images, call it once per image.
It runs in the background: the call starts a job and returns right away, and you are notified automatically when the image is saved, with its path. Never poll, sleep, or check for the file while you wait.
Don't repeat a request unless the user asks.";

pub fn spec() -> (String, Value) {
    (
        DESCRIPTION.into(),
        json!({
            "type": "object",
            "properties": {
                "prompt": {"type": "string", "minLength": 1, "description": "What to create, or for edits, what to change. Be specific about subject, style, composition and any text that should appear in the image."},
                "images": {"type": "array", "minItems": 1, "maxItems": 8, "items": {"type": "string", "minLength": 1}, "description": "Images to edit, or to use as references for style and subject when creating a new image, in order. Local file paths (relative to the session directory or absolute) or http(s) URLs."},
                "model": {"type": "string", "description": "NEVER set this unless the user explicitly asks for a particular image model or variant. The value is written as \"providerID/modelID\", or \"providerID/modelID#variant\" to include a variant. Do not guess the ID."},
                "path": {"type": "string", "description": "Where to save the image, relative to the session directory or absolute. The extension is replaced with the image's real format, and an existing file is overwritten. Defaults to a new file in the session's temp folder."}
            },
            "required": ["prompt"]
        }),
    )
}

/// Whether config leaves the tool on: `experimental.image_generate: false`
/// turns it off (permissions are the other way).
pub fn enabled(config: &Config) -> bool {
    config.experimental.image_generate.as_ref() != Some(&Value::Bool(false))
}

/// `experimental.image_generate.model`, the preferred model.
pub fn configured_model(config: &Config) -> Option<String> {
    model_setting(config.experimental.image_generate.as_ref()?)
}

/// A configured model: `"provider/model#variant"`, or OpenCode's
/// `{"providerID", "model", "variant"}`.
pub fn model_setting(v: &Value) -> Option<String> {
    match &v["model"] {
        Value::String(s) => Some(s.clone()),
        Value::Object(o) => {
            let p = o.get("providerID")?.as_str()?;
            let m = o.get("model")?.as_str()?;
            Some(match o.get("variant").and_then(Value::as_str) {
                Some(v) => format!("{p}/{m}#{v}"),
                None => format!("{p}/{m}"),
            })
        }
        _ => None,
    }
}

/// Offered while an image model is reachable and config leaves it on.
pub fn offered(config: &Config) -> bool {
    enabled(config) && !generate::models(config, "image").is_empty()
}

/// The newest image model from the session's provider, else the newest
/// (OpenCode's `defaultModel`); with `images`, only models that take them.
pub fn default_model<'a>(
    available: &'a [MediaModel],
    provider: Option<&str>,
    images: bool,
) -> Option<&'a MediaModel> {
    let mut candidates = available.iter().filter(|m| !images || m.accepts_images());
    let first = candidates.clone().next();
    candidates
        .find(|m| Some(m.provider_id.as_str()) == provider)
        .or(first)
}

/// The model to use, its variant, and a note when a configured default
/// could not be used.
pub fn resolve_model(
    config: &Config,
    available: &[MediaModel],
    input: Option<&str>,
    provider: Option<&str>,
    images: bool,
) -> Result<(MediaModel, Option<String>, String), String> {
    let Some(input) = input else {
        let configured = configured_model(config);
        let parsed = configured.as_deref().and_then(generate::parse_ref);
        let preferred =
            parsed.and_then(|(p, m, _)| available.iter().find(|x| x.provider_id == p && x.id == m));
        let variant = parsed.and_then(|(_, _, v)| v);
        let variant_missing = variant
            .is_some_and(|v| preferred.is_some_and(|m| !m.variants.iter().any(|(n, _)| n == v)));
        if let Some(m) = preferred {
            if !variant_missing && (!images || m.accepts_images()) {
                return Ok((m.clone(), variant.map(str::to_string), String::new()));
            }
        }
        let Some(model) = default_model(available, provider, images) else {
            return Err(if images {
                "None of the available image models accept input images.".into()
            } else {
                "No image model is available.".into()
            });
        };
        let Some(configured) = configured.as_deref() else {
            return Ok((model.clone(), None, String::new()));
        };
        let reason = if preferred.is_none() {
            "isn't available".to_string()
        } else if variant_missing {
            format!("has no variant \"{}\"", variant.unwrap_or_default())
        } else {
            "doesn't accept input images".to_string()
        };
        let note = format!(" {configured} {reason}; used {}.", model.spec());
        return Ok((model.clone(), None, note));
    };
    let (p, m, variant) = generate::parse_ref(input).ok_or_else(|| {
        format!("Invalid model \"{input}\". Use \"providerID/modelID\" or \"providerID/modelID#variant\".")
    })?;
    let model = available
        .iter()
        .find(|x| x.provider_id == p && x.id == m)
        .ok_or_else(|| format!("Model \"{p}/{m}\" is not an available image model."))?;
    if let Some(v) = variant {
        if !model.variants.iter().any(|(n, _)| n == v) {
            return Err(if model.variants.is_empty() {
                format!("Model \"{p}/{m}\" has no variants. Omit the variant.")
            } else {
                let names: Vec<&str> = model.variants.iter().map(|(n, _)| n.as_str()).collect();
                format!(
                    "Variant \"{v}\" is not available for \"{p}/{m}\". Available: {}.",
                    names.join(", ")
                )
            });
        }
    }
    if images && !model.accepts_images() {
        let capable: Vec<String> = available
            .iter()
            .filter(|x| x.accepts_images())
            .take(3)
            .map(MediaModel::spec)
            .collect();
        return Err(if capable.is_empty() {
            format!("Model \"{p}/{m}\" does not accept input images, and no available image model does.")
        } else {
            format!(
                "Model \"{p}/{m}\" does not accept input images. Image models that do: {}.",
                capable.join(", ")
            )
        });
    }
    Ok((model.clone(), variant.map(str::to_string), String::new()))
}

/// The extension an image of `mime` is saved with.
pub fn extension(mime: &str) -> &'static str {
    match mime {
        "image/jpeg" => ".jpg",
        "image/webp" => ".webp",
        "image/gif" => ".gif",
        _ => ".png",
    }
}

/// The completion notice for a background image job.
pub fn notice(id: &str, state: &str, body: &str) -> String {
    format!("<image id=\"{id}\" state=\"{state}\">\n{body}\n</image>")
}

/// Read one input image: a file the agent may read, or a URL it may fetch,
/// of at most 20 MiB, that is a PNG, JPEG, WebP or GIF.
pub async fn read_image(ctx: &Ctx<'_>, source: &str) -> Result<Media, String> {
    let name = Path::new(source)
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| source.to_string());
    let bytes = if is_url(source) {
        download(ctx, source, MAX_INPUT_BYTES as usize).await?
    } else {
        let path = super::read::authorize(ctx, source)?;
        let meta = std::fs::metadata(&path).map_err(|_| format!("File not found: {source}"))?;
        if meta.len() > MAX_INPUT_BYTES {
            return Err(format!("{source} is larger than 20 MiB."));
        }
        std::fs::read(&path).map_err(|e| format!("Unable to read {source}: {e}"))?
    };
    let mime = crate::media::detect(&bytes[..bytes.len().min(crate::media::SNIFF_BYTES)])
        .filter(|m| INPUT_TYPES.contains(m))
        .ok_or_else(|| format!("{source} is not a PNG, JPEG, WebP or GIF image."))?;
    Ok(Media::base64(mime, crate::media::base64(&bytes)).named(name))
}

pub fn is_url(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    l.starts_with("http://") || l.starts_with("https://")
}

/// Fetch `url` under the `webfetch` rule (denying web access covers media
/// URLs too), with webfetch's safeguards: http(s) only, no credentials in
/// the URL, "always" saving only its origin, and each redirect checked
/// against the rules. Bounded in time and size.
pub async fn download(ctx: &Ctx<'_>, url: &str, max: usize) -> Result<Vec<u8>, String> {
    // Rules match the URL as written; the fragment is never sent.
    let url = url.split('#').next().unwrap_or(url);
    let parsed = reqwest::Url::parse(url).map_err(|e| format!("Invalid URL {url:?}: {e}"))?;
    super::webfetch::check_url(&parsed)?;
    ctx.ask(Request {
        action: "webfetch".into(),
        resources: vec![url.to_string()],
        save: super::webfetch::save_patterns(url),
        title: format!("Fetch {url}"),
    })?;
    let fetch =
        async {
            let mut resp = super::webfetch::get_following(ctx, url, |rb| rb).await?;
            if !resp.status().is_success() {
                return Err(format!(
                    "Unable to download {url}: HTTP {}",
                    resp.status().as_u16()
                ));
            }
            if resp.content_length().is_some_and(|n| n > max as u64) {
                return Err(format!("{url} is larger than {} MiB.", max / (1024 * 1024)));
            }
            let mut out = Vec::new();
            while let Some(chunk) = resp.chunk().await.map_err(|e| {
                format!("Unable to download {url}: {}", codesmith_ai::Error::from(e))
            })? {
                out.extend_from_slice(&chunk);
                if out.len() > max {
                    return Err(format!("{url} is larger than {} MiB.", max / (1024 * 1024)));
                }
            }
            Ok(out)
        };
    tokio::time::timeout(DOWNLOAD_TIMEOUT, fetch)
        .await
        .map_err(|_| format!("Timed out downloading {url}."))?
}

/// A short random id part.
pub fn job_suffix() -> String {
    use rand::Rng;
    format!(
        "{:012x}",
        rand::thread_rng().gen::<u64>() & 0xffff_ffff_ffff
    )
}

/// What [`run`] needs from the session beyond the tool context.
pub struct Env<'a> {
    pub config: &'a Config,
    /// The session's provider, preferred when the model is picked.
    pub provider: Option<&'a str>,
    /// The session database, whose blob store keeps the image.
    pub store: Option<PathBuf>,
    /// The gate, for the background job's own check when the real format
    /// renames the file.
    pub gate: Gate,
    pub jobs: Jobs,
    pub retry: generate::Options,
}

/// Start an image job; returns the call's text.
pub async fn run(ctx: &Ctx<'_>, env: Env<'_>, input: &Value) -> Result<String, String> {
    start(ctx, env, input)
        .await
        .map_err(|e| format!("Unable to generate image: {e}"))
}

async fn start(ctx: &Ctx<'_>, env: Env<'_>, input: &Value) -> Result<String, String> {
    let prompt = input["prompt"]
        .as_str()
        .filter(|p| !p.is_empty())
        .ok_or("Missing required parameter `prompt`")?
        .to_string();
    let sources: Option<Vec<String>> = match input.get("images") {
        None | Some(Value::Null) => None,
        Some(Value::Array(a)) => Some(
            a.iter()
                .map(|v| v.as_str().filter(|s| !s.is_empty()).map(str::to_string))
                .collect::<Option<Vec<_>>>()
                .filter(|v| (1..=8).contains(&v.len()))
                .ok_or("`images` must list 1 to 8 paths or URLs")?,
        ),
        Some(_) => return Err("`images` must list 1 to 8 paths or URLs".into()),
    };
    let available = generate::models(env.config, "image");
    let (model, variant, note) = resolve_model(
        env.config,
        &available,
        input["model"].as_str(),
        env.provider,
        sources.is_some(),
    )?;
    let reference = match &variant {
        Some(v) => format!("{}#{v}", model.spec()),
        None => model.spec(),
    };
    let target = input["path"].as_str().map(|p| ctx.resolve(p));
    // The file takes the extension of the image's real format.
    let stem = match &target {
        Some(t) => t.absolute.with_extension(""),
        None => crate::paths::tmp_dir()
            .join("images")
            .join(&ctx.session_id)
            .join(format!("image_{}", job_suffix())),
    };
    ctx.ask(Request {
        action: NAME.into(),
        resources: vec![reference.clone()],
        save: vec!["*".into()],
        title: format!("Generate an image with {reference}"),
    })?;
    if let Some(t) = &target {
        ctx.authorize_external(t, false)?;
        ctx.ask(Request {
            action: "edit".into(),
            resources: t.resources.clone(),
            save: vec!["*".into()],
            title: format!("Write {}", t.resource),
        })?;
    }
    let mut images = Vec::new();
    for s in sources.iter().flatten() {
        images.push(read_image(ctx, s).await?);
    }
    // Everything that needs the user or can fail fast is done; the paid
    // call runs as a background job.
    let id = format!("image_{}", job_suffix());
    let job = Job {
        config: env.config.clone(),
        client: ctx.client.clone(),
        input: generate::ImageInput {
            model: reference.clone(),
            prompt: prompt.clone(),
            images,
            n: Some(1),
            ..Default::default()
        },
        reference: reference.clone(),
        stem: stem.clone(),
        requested: target
            .as_ref()
            .map(|t| (t.absolute.clone(), t.real.clone())),
        gate: env.gate,
        cwd: ctx.cwd.clone(),
        root: ctx.root.clone(),
        session: ctx.session_id.clone(),
        store: env.store,
        retry: env.retry,
    };
    let (done_id, cancel_id) = (id.clone(), id.clone());
    let shown = stem.display().to_string();
    let cancelled_text = notice(
        &cancel_id,
        "cancelled",
        &format!("Image request for {shown} was cancelled."),
    );
    env.jobs.spawn_task(
        &id,
        &prompt,
        async move {
            match job.run().await {
                Ok(text) => notice(&done_id, "completed", &text),
                Err(e) => notice(&done_id, "error", &e),
            }
        },
        async move { cancelled_text },
    );
    Ok([
        format!("Image job {id} started in the background with {reference}. It will be saved as {shown} with the extension of its real format (.png, .jpg, .webp or .gif); the notice gives the exact path.{note}"),
        "You will be notified automatically when it finishes or fails.".into(),
        "DO NOT sleep, poll, check whether the file exists, or request the same image again while it runs.".into(),
        "Work on other tasks, or briefly tell the user what you started and end your response.".into(),
    ]
    .join("\n"))
}

/// The background half of a call.
struct Job {
    config: Config,
    client: reqwest::Client,
    input: generate::ImageInput,
    reference: String,
    stem: PathBuf,
    /// The path the call asked for, as named and with symlinks resolved
    /// when it was approved.
    requested: Option<(PathBuf, PathBuf)>,
    gate: Gate,
    cwd: PathBuf,
    root: PathBuf,
    session: String,
    store: Option<PathBuf>,
    retry: generate::Options,
}

impl Job {
    async fn run(self) -> Result<String, String> {
        let failed = |e: String| format!("Image request failed for {}: {e}", self.stem.display());
        let result = tokio::time::timeout(
            generate::IMAGE_TIMEOUT,
            generate::image(&self.config, &self.client, &self.input, self.retry),
        )
        .await
        .map_err(|_| failed("Image generation timed out after 30 minutes.".into()))?
        .map_err(|e| failed(e.to_string()))?;
        let image = result
            .images
            .into_iter()
            .next()
            .ok_or_else(|| failed(format!("{} returned no image.", self.reference)))?;
        let mime =
            crate::media::detect(&image.data[..image.data.len().min(crate::media::SNIFF_BYTES)])
                .unwrap_or("image/png");
        let file = PathBuf::from(format!("{}{}", self.stem.display(), extension(mime)));
        let ctx = Ctx {
            cwd: self.cwd.clone(),
            root: self.root.clone(),
            gate: &self.gate,
            shell: String::new(),
            session_id: self.session.clone(),
            limits: Default::default(),
            client: self.client.clone(),
            jobs: None,
            websearch: None,
            format: None,
            lsp: None,
            progress: None,
        };
        let t = ctx.resolve(&file.display().to_string());
        // The edit prompt covered the requested path, where it led when it
        // was approved. Another path (the extension changed) gets the
        // checks a write does: outside the project it needs its own
        // approval, and replacing an existing file asks; a new one only has
        // to pass the deny rules.
        match &self.requested {
            Some((requested, real)) if &file == requested => {
                if &t.real != real {
                    return Err(failed(format!(
                        "{} now leads somewhere else than when it was approved.",
                        file.display()
                    )));
                }
            }
            Some(_) => {
                ctx.authorize_external(&t, false).map_err(failed)?;
                if file.exists() {
                    ctx.ask(Request {
                        action: "edit".into(),
                        resources: t.resources.clone(),
                        save: vec!["*".into()],
                        title: format!("Write {}", t.resource),
                    })
                    .map_err(failed)?;
                } else {
                    ctx.check_not_denied("edit", &t.resources).map_err(failed)?;
                }
            }
            None => {}
        }
        let bytes = through_blob_store(self.store.as_deref(), &self.session, &image.data, mime);
        if let Some(dir) = file.parent() {
            std::fs::create_dir_all(dir).map_err(|e| failed(e.to_string()))?;
        }
        // Checked again just before writing: what was allowed must still be
        // where the path leads, and the file itself is never a symlink.
        if ctx.resolve(&file.display().to_string()).real != t.real {
            return Err(failed(format!(
                "{} changed while the image was being written.",
                file.display()
            )));
        }
        write_no_follow(&file, &bytes).map_err(|e| failed(e.to_string()))?;
        Ok(format!(
            "Image request finished. Saved image: {} ({}).\nUse the read tool on this path to view the image.",
            file.display(),
            self.reference
        ))
    }
}

/// Create or replace the file at `path` with `data`, refusing to follow a
/// symlink there.
fn write_no_follow(path: &Path, data: &[u8]) -> std::io::Result<()> {
    use std::io::Write;
    if std::fs::symlink_metadata(path).is_ok_and(|m| m.file_type().is_symlink()) {
        return Err(std::io::Error::other(format!(
            "{} is a symlink; not writing through it",
            path.display()
        )));
    }
    let mut opts = std::fs::OpenOptions::new();
    opts.write(true).create(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        opts.custom_flags(libc::O_NOFOLLOW);
    }
    let mut f = opts.open(path)?;
    f.write_all(data)
}

/// Keep `data` in the session's blob store (once, however often it is
/// made; deleted with the session) and return the stored bytes. Without a
/// store, or past the cap, the bytes pass through as they are.
pub fn through_blob_store(store: Option<&Path>, session: &str, data: &[u8], mime: &str) -> Vec<u8> {
    let Some(st) = store.and_then(|p| crate::store::Store::open(p).ok()) else {
        return data.to_vec();
    };
    match st.put_blob(session, data, mime) {
        Ok(Some(h)) => st
            .blob(&h)
            .ok()
            .flatten()
            .map(|(_, b)| b)
            .unwrap_or_else(|| data.to_vec()),
        _ => data.to_vec(),
    }
}

#[cfg(test)]
mod url_tests {
    use super::*;
    use crate::permission::{Effect, Fixed, Reply, Rule};
    use crate::tool::testing::{serve, Env};
    use std::sync::Arc;

    fn png() -> Vec<u8> {
        crate::media::unbase64(
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
        )
        .unwrap()
    }

    #[test]
    fn the_image_file_is_never_written_through_a_symlink() {
        let d = tempfile::tempdir().unwrap();
        let victim = d.path().join("victim");
        std::fs::write(&victim, "keep").unwrap();
        let link = d.path().join("out.png");
        std::os::unix::fs::symlink(&victim, &link).unwrap();
        assert!(write_no_follow(&link, b"img").is_err());
        assert_eq!(std::fs::read_to_string(&victim).unwrap(), "keep");
        let plain = d.path().join("plain.png");
        write_no_follow(&plain, b"img").unwrap();
        write_no_follow(&plain, b"i2").unwrap();
        assert_eq!(std::fs::read(&plain).unwrap(), b"i2");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn an_input_url_with_credentials_is_refused_before_asking() {
        let (env, rec) = Env::recording(vec![]);
        let err = read_image(&env.ctx(), "https://user@example.test/x.png")
            .await
            .unwrap_err();
        assert!(err.contains("credentials"), "{err}");
        assert!(rec.actions().is_empty());
        let err = read_image(&env.ctx(), "https://a:b@example.test/x.png")
            .await
            .unwrap_err();
        assert!(err.contains("credentials"), "{err}");
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn each_redirect_of_an_input_url_is_checked_against_the_rules() {
        let (denied, denied_seen) = serve(|_| (200, String::new(), png())).await;
        let to = format!("{denied}/b.png");
        let (base, _) = serve(move |_| (302, format!("location: {to}\r\n"), Vec::new())).await;
        let mut env = Env::new();
        env.gate = Gate::new(
            vec![
                Rule::new("webfetch", "*", Effect::Allow),
                Rule::new("webfetch", &format!("{denied}/*"), Effect::Deny),
            ],
            Arc::new(Fixed(Reply::Once)),
        );
        let err = read_image(&env.ctx(), &format!("{base}/a.png"))
            .await
            .unwrap_err();
        assert!(err.contains("denied") || err.contains("Denied"), "{err}");
        assert!(denied_seen.lock().unwrap().is_empty());
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn always_saves_only_the_input_urls_origin() {
        let (base, seen) = serve(|_| (200, String::new(), png())).await;
        let env = Env::with_reply(Reply::Always);
        let m = read_image(&env.ctx(), &format!("{base}/a.png#frag"))
            .await
            .unwrap();
        assert_eq!(m.mime, "image/png");
        assert_eq!(seen.lock().unwrap().clone(), vec!["/a.png".to_string()]);
        let saved: Vec<String> = env.gate.saved().into_iter().map(|r| r.resource).collect();
        assert_eq!(saved, vec![base.clone(), format!("{base}/*")]);
    }
}
